"""Gemma 4 Developer Agent: write submission.zip (built by gemma4-agent/kernels/pack/build.py)."""
import os
import subprocess
import sys
import zipfile

FILES = {
 "agent.yaml": "name: swe_agent\nmodel: gemma-4-31b-it-qat-w4a16-ct\ninstruction: !include prompts/system.md\ntools:\n  - run_command\n  - read_file\n  - edit_file\n  - write_file\n  - get_status\n  - submit_patch\ngenerate_content_config: !include configs/sampling.yaml\n",
 "eval_config.yaml": "evaluation:\n  timeout_seconds: 150\n  max_tool_calls: 28\n  max_time_minutes: 7\n  max_turns: 80\n",
 "configs/sampling.yaml": "temperature: 1.0\ntop_p: 0.95\ntop_k: 64\nmax_output_tokens: 8192\nthinking_config:\n  thinking_budget: 4096\n  include_thoughts: true\n",
 "prompts/system.md": "You are an expert autonomous software engineer. Resolve the user issue with the smallest source change that satisfies the stated behavior.\n\nThe hidden grader applies your git diff to a fresh repository and runs its own tests. It never sees your reasoning. An empty diff scores zero. A correct source diff scores the task even if your local test was red or you never ran a test.\n\n## Budget\nYou have 28 tool calls and 7 minutes. When either limit hits, the working tree is graded as it is. An edit made in time counts even if you do not reach submit_patch. Finish as soon as the edit is in so later tasks still have time.\nTime guard: call `get_status` (free) right after your first edit. If it shows less than 150 seconds remaining, skip the check and call `submit_patch` now. Any command is killed after 150 seconds, so wrap a test run in `timeout 90`.\n\n## 1. Contract, before any tool call\nRead the issue and keep a short list of the exact symbols, signatures, error strings, HTTP status codes, and return values it requires. Copy them character for character. The grader checks those strings exactly.\n\n## 2. Locate in a few reads\n- Search once with `git grep -n \"SPECIFIC_TOKEN\" -- '*.py' | head -20`. Use the most specific identifier or error string from the issue.\n- Open only the matching region with `read_file`, at most 120 lines (`start_line` and `end_line`).\n- You may do one follow-up grep or read if the first hit only re-exports the symbol.\n- Do not page through unrelated files. Do not read a whole file when a range will do.\n\n## 3. Edit by tool call 12\n- By your 12th tool call a source file must already be edited. If it is not, edit the most likely function immediately. Runs that are still only reading after 12 calls almost never succeed.\n- Prefer `edit_file`. `old_string` must match the file exactly, including indentation. Change the smallest span that implements the contract.\n- FastAPI documentation tasks: edit the executable example under `docs_src/`.\n- Do not reformat or refactor unrelated code.\n- Create a new file only when the issue explicitly requires a new module. Never create or edit `test_*.py`, `*_test.py`, anything under `tests/`, `pytest.ini`, or `conftest.py`.\n- Any scratch script goes in `/tmp` through `run_command`. Never write scratch files into `/workspace`. Files left in the repository become part of the diff and fail grading.\n\n## 4. One check, one repair, then submit\n- After the edit, run at most one focused check: `timeout 90 python -m pytest tests/test_file.py -k test_name -q` or `python -c \"...\"`.\n- Never run bare `pytest`, `pytest .`, or `python -m unittest discover`.\n- If that check fails with an assertion about the behavior you changed, apply one `edit_file` using the assertion text, then stop testing.\n- If it fails because of missing fixtures, import errors, or pre-existing breakage, ignore it. Do not repair tests and do not install packages.\n- Call `submit_patch` after that, even when the local check is red or you skipped it. A local green test is not the grader.\n- If the diff contains a test path, run `git checkout --` on that path and call `submit_patch` again.\n- If `get_status` shows less than 150 seconds remaining, call `submit_patch` immediately.\n\n## Never\n- Conclude that the code is already correct. Every task needs a source modification and a non-empty patch.\n- Search outside `/workspace` (`/usr`, `/wheels`, `/opt`). Dependencies are already installed.\n- Spend calls on broad exploration after the first edit.\n"
}
ZERO_LORAS = {}
GEN_SRC = "\"\"\"Write a rank-r PEFT LoRA adapter for gemma-4-31b-it whose B matrices are zero (the model's output is unchanged).\n\nUsed for the LoRA feasibility probe (10-24 plan audit): does a submission with adapters/ start vLLM (LoRA enabled,\nmax_lora_rank = r) and finish the hidden run within 12 h with the smaller KV cache? Only q_proj of the 60 text layers\nis targeted (sliding layers: 5376 -> 32 x 256, full layers: 5376 -> 32 x 512, from the model's config.json).\nNo numpy/torch needed: safetensors is written by hand (bf16).\n\n    python make_zero_lora.py OUT_DIR [rank]\n\"\"\"\nimport json\nimport os\nimport random\nimport struct\nimport sys\n\nout = sys.argv[1]\nr = int(sys.argv[2]) if len(sys.argv) > 2 else 8\nH, NH, HD, GHD, L = 5376, 32, 256, 512, 60\nfull = {i for i in range(L) if i % 6 == 5}      # layer_types: every 6th layer is full_attention (5, 11, ..., 59)\n\n\ndef bf16(x):\n    return struct.unpack(\">I\", struct.pack(\">f\", x))[0] >> 16\n\n\ntensors = {}\nrng = random.Random(0)\nfor i in range(L):\n    out_f = NH * (GHD if i in full else HD)\n    pre = f\"base_model.model.model.language_model.layers.{i}.self_attn.q_proj\"\n    a = bytearray()\n    bound = 1.0 / (H ** 0.5)\n    for _ in range(r * H):\n        a += struct.pack(\"<H\", bf16(rng.uniform(-bound, bound)))\n    tensors[pre + \".lora_A.weight\"] = ([r, H], bytes(a))\n    tensors[pre + \".lora_B.weight\"] = ([out_f, r], bytes(2 * out_f * r))\n\nheader, off, blobs = {}, 0, []\nfor k in sorted(tensors):\n    shape, b = tensors[k]\n    header[k] = {\"dtype\": \"BF16\", \"shape\": shape, \"data_offsets\": [off, off + len(b)]}\n    off += len(b)\n    blobs.append(b)\nheader[\"__metadata__\"] = {\"format\": \"pt\"}\nhj = json.dumps(header, separators=(\",\", \":\")).encode()\nhj += b\" \" * ((8 - len(hj) % 8) % 8)\nos.makedirs(out, exist_ok=True)\nwith open(os.path.join(out, \"adapter_model.safetensors\"), \"wb\") as f:\n    f.write(struct.pack(\"<Q\", len(hj)))\n    f.write(hj)\n    for b in blobs:\n        f.write(b)\ncfg = {\"peft_type\": \"LORA\", \"task_type\": \"CAUSAL_LM\", \"base_model_name_or_path\": \"google/gemma-4-31b-it\",\n       \"r\": r, \"lora_alpha\": 2 * r, \"lora_dropout\": 0.0, \"bias\": \"none\", \"fan_in_fan_out\": False,\n       \"target_modules\": [\"q_proj\"], \"layers_to_transform\": None, \"modules_to_save\": None,\n       \"inference_mode\": True, \"use_rslora\": False, \"use_dora\": False, \"init_lora_weights\": True}\njson.dump(cfg, open(os.path.join(out, \"adapter_config.json\"), \"w\"), indent=2)\nprint(\"wrote\", out, \"rank\", r, \"tensors\", len(tensors), \"bytes\", off)\n"

os.makedirs("/kaggle/working", exist_ok=True)
with zipfile.ZipFile("/kaggle/working/submission.zip", "w", zipfile.ZIP_DEFLATED) as z:
    for name, text in sorted(FILES.items()):
        z.writestr(name, text)
        print(name, len(text))
    if ZERO_LORAS:
        open("/tmp/make_zero_lora.py", "w").write(GEN_SRC)
        for d, r in sorted(ZERO_LORAS.items()):
            out = os.path.join("/tmp/zl", d)
            subprocess.check_call([sys.executable, "/tmp/make_zero_lora.py", out, str(r)])
            for f in ("adapter_config.json", "adapter_model.safetensors"):
                z.write(os.path.join(out, f), d + "/" + f)
                print(d + "/" + f, os.path.getsize(os.path.join(out, f)))
print("wrote /kaggle/working/submission.zip")
